function cn(...classes: (string | false | undefined)[]) { return classes.filter(Boolean).join(' '); }

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-center gap-2.5" data-testid="brand-logo">
    <div className="grid size-9 place-items-center rounded-xl bg-primary text-primary-foreground shadow-sm"><Sparkles size={18} /></div>
    {!compact && <div><p className="display-font text-sm font-bold leading-none">orbit campus</p><p className="mt-1 text-[10px] font-semibold uppercase tracking-[.18em] text-muted-foreground">your daily edge</p></div>}
  </div>;
}

function Avatar({ role, small = false }: { role: Role; small?: boolean }) {
  const person = roleInfo[role];
  return <div className={cn('grid shrink-0 place-items-center rounded-full bg-accent font-bold text-accent-foreground', small ? 'size-8 text-[11px]' : 'size-10 text-xs')} data-testid={`avatar-${role}`}>{person.initials}</div>;
}

function StatCard({ label, value, detail, icon: Icon, tone = 'teal' }: { label: string; value: string; detail: string; icon: IconType; tone?: 'teal' | 'orange' | 'purple' }) {
  const tones = { teal: 'bg-secondary text-primary', orange: 'bg-[#f9e3cf] text-[#9a5a2d]', purple: 'bg-[#e9e2f4] text-[#72519a]' };
  return <div className="rounded-2xl border bg-card p-4 soft-shadow" data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`}>
    <div className="flex items-start justify-between gap-2"><p className="text-xs font-semibold text-muted-foreground">{label}</p><div className={cn('grid size-8 place-items-center rounded-xl', tones[tone])}><Icon size={16} /></div></div>
    <p className="display-font mt-3 text-2xl font-bold tracking-tight">{value}</p><p className="mt-1 text-[11px] text-muted-foreground">{detail}</p>
  </div>;
}

function SectionHeading({ eyebrow, title, action, onAction }: { eyebrow?: string; title: string; action?: string; onAction?: () => void }) {
  return <div className="mb-4 flex items-end justify-between gap-3"><div>{eyebrow && <p className="mb-1 text-[10px] font-bold uppercase tracking-[.18em] text-primary">{eyebrow}</p>}<h2 className="display-font text-lg font-bold tracking-tight">{title}</h2></div>{action && <button onClick={onAction} className="flex items-center gap-1 text-xs font-bold text-primary" data-testid={`button-${action.toLowerCase().replaceAll(' ', '-')}`}>{action}<ChevronRight size={14} /></button>}</div>;
}

function Progress({ value, color = 'bg-primary' }: { value: number; color?: string }) {
  return <div className="h-2 overflow-hidden rounded-full bg-muted"><div className={cn('h-full rounded-full transition-all duration-500', color)} style={{ width: `${value}%` }} /></div>;
}

